import * as THREE from 'three/webgpu';
import {
  texture,
  float,
  color,
  standardMaterial
} from 'three/tsl';
import { gsap } from 'gsap';
import { createMSDFText } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const { position = { x: 0, y: 0, z: 0 }, rotation = { x: 0, y: 0, z: 0 }, scale = { x: 1, y: 1, z: 1 } } = config;
  group.position.set(position.x, position.y, position.z);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.set(scale.x, scale.y, scale.z);

  // Load base texture (used for all plates)
  const baseTexture = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');

  // Caption texts (order corresponds to plates)
  const captionTexts = [
    'DIAL ROOM',
    'ESCAPEMENT BENCH',
    'CNC HALL',
    'FINISHING LAB',
    'ARCHIVE VAULT',
    'ASSEMBLY LINE ONE'
  ];

  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const platePitch = 1.5;
  const columnOffsetX = 0.9;
  const bevelSize = 0.03;
  const accentStripWidth = 0.03;
  const accentColor = 0xff2a38;

  const disposables = {
    geometries: [],
    materials: [],
    textures: new Set(),
    timelines: []
  };

  // Create plates
  for (let i = 0; i < 6; i++) {
    const plateGroup = new THREE.Group();

    // Main plate mesh
    const planeGeom = new THREE.PlaneGeometry(plateWidth, plateHeight);
    disposables.geometries.push(planeGeom);
    const plateMat = standardMaterial({
      map: texture(baseTexture),
      roughness: float(0.6),
      metalness: float(0.1),
      clearcoat: float(0.1)
    });
    disposables.materials.push(plateMat);
    const plateMesh = new THREE.Mesh(planeGeom, plateMat);
    plateGroup.add(plateMesh);

    // Bevel frame
    const bevelGeom = new THREE.PlaneGeometry(plateWidth + bevelSize * 2, plateHeight + bevelSize * 2);
    disposables.geometries.push(bevelGeom);
    const bevelMat = standardMaterial({
      color: color('#16161d'),
      roughness: float(0.5),
      metalness: float(0.5)
    });
    disposables.materials.push(bevelMat);
    const bevelMesh = new THREE.Mesh(bevelGeom, bevelMat);
    bevelMesh.position.set(0, 0, -0.001);
    plateGroup.add(bevelMesh);

    // Accent strip (only for the plate nearest y = 0, which is i == 0 after positioning)
    if (i === 0) {
      const stripGeom = new THREE.PlaneGeometry(accentStripWidth, plateHeight);
      disposables.geometries.push(stripGeom);
      const stripMat = standardMaterial({
        emissive: color('#ff2a38'),
        emissiveIntensity: float(1.4)
      });
      disposables.materials.push(stripMat);
      const stripMesh = new THREE.Mesh(stripGeom, stripMat);
      stripMesh.position.set(-plateWidth / 2 + accentStripWidth / 2, 0, 0.001);
      plateGroup.add(stripMesh);
    }

    // Caption text
    const caption = captionTexts[i] || '';
    const captionObj = createMSDFText(ctx.fontAtlas, caption, {
      fontSize: 0.13,
      fontFamily: 'JetBrains Mono',
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: '#e8ecf2'
    });
    captionObj.position.set(-1.6, 0, 0.02);
    plateGroup.add(captionObj);

    // Position plate group in column
    plateGroup.position.set(columnOffsetX, i * platePitch, 0);
    group.add(plateGroup);
  }

  // Headline text
  const headlineObj = createMSDFText(ctx.fontAtlas, 'Inside the atelier', {
    fontSize: 0.62,
    fontFamily: 'Lora',
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2'
  });
  headlineObj.position.set(-1.6, 1.9, 0);
  group.add(headlineObj);

  // Apply cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      if (typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](group, primitive.params);
      }
    }
  }

  // Example GSAP timeline for possible future scroll inertia (kept for cleanup)
  const dummyTimeline = gsap.timeline({ paused: true });
  disposables.timelines.push(dummyTimeline);

  // Cleanup
  group.userData.cleanup = () => {
    disposables.geometries.forEach(g => g.dispose());
    disposables.materials.forEach(m => m.dispose());
    disposables.textures.forEach(t => {
      if (t && t.dispose) t.dispose();
    });
    disposables.timelines.forEach(tl => tl.kill());
    group.traverse(child => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose && m.dispose());
          } else {
            child.material.dispose && child.material.dispose();
          }
        }
      }
    });
  };

  // Register texture for disposal tracking
  disposables.textures.add(baseTexture);

  return group;
}
